"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[31998],{79472:e=>{e.exports=JSON.parse('{"functions":[{"name":"ListenToEvent","desc":"Subscribes to a named `BindableEvent` and returns its `RBXScriptSignal`.\\nThe event is created and cached on first access.  The name is registered\\nas an active listener so subsequent `Fire` calls will proceed.","params":[{"name":"eventName","desc":"Case-insensitive event name.","lua_type":"string"}],"returns":[{"desc":"The underlying `BindableEvent.Event` signal.","lua_type":"RBXScriptSignal"}],"function_type":"method","source":{"line":60,"path":"src/ReplicatedStorage/SharedModules/BindableCore.luau"}},{"name":"Fire","desc":"Fires the named `BindableEvent` with the given arguments.  Warns and\\nreturns early if no active listener has been registered for this name.","params":[{"name":"eventName","desc":"Case-insensitive event name.","lua_type":"string"},{"name":"...","desc":"Arguments forwarded to all connected callbacks.","lua_type":"any"}],"returns":[],"function_type":"method","source":{"line":76,"path":"src/ReplicatedStorage/SharedModules/BindableCore.luau"}},{"name":"Invoke","desc":"Invokes the named `BindableFunction` and returns its result.  Warns and\\nreturns `nil` early if no active listener has been registered for this\\nname.","params":[{"name":"eventName","desc":"Case-insensitive function name.","lua_type":"string"},{"name":"...","desc":"Arguments forwarded to the `OnInvoke` callback.","lua_type":"any"}],"returns":[{"desc":"Value(s) returned by the `OnInvoke` callback.","lua_type":"any"}],"function_type":"method","source":{"line":98,"path":"src/ReplicatedStorage/SharedModules/BindableCore.luau"}},{"name":"ListenToFunction","desc":"Binds `callback` as the `OnInvoke` handler for a named `BindableFunction`\\nand registers the name as an active listener.","params":[{"name":"eventName","desc":"Case-insensitive function name.","lua_type":"string"},{"name":"callback","desc":"Handler invoked when `Invoke` is called.","lua_type":"(...any) -> ...any"}],"returns":[],"function_type":"method","source":{"line":118,"path":"src/ReplicatedStorage/SharedModules/BindableCore.luau"}}],"properties":[],"types":[],"name":"BindableCore","desc":"Name-based `BindableEvent` / `BindableFunction` wrapper that manages\\ncreation, caching, and listener tracking automatically.\\n\\nEvent names are normalised to lower-case and prefixed with `CLIENT_` or\\n`SERVER_` depending on the current network side, so the same name string\\nis safe to use from both contexts without collision.\\n\\n**Typical workflow:**\\n\\n```lua\\n-- Producer (fires the event)\\nBindableCore:Fire(\\"myEvent\\", payload)\\n\\n-- Consumer (subscribes before the first fire)\\nBindableCore:ListenToEvent(\\"myEvent\\"):Connect(function(payload)\\n\\t-- handle payload\\nend)\\n```\\n\\nFor request/response patterns use `ListenToFunction` + `Invoke`:\\n\\n```lua\\nBindableCore:ListenToFunction(\\"getScore\\", function(playerId)\\n\\treturn scores[playerId]\\nend)\\n\\nlocal score = BindableCore:Invoke(\\"getScore\\", player.UserId)\\n```","source":{"line":38,"path":"src/ReplicatedStorage/SharedModules/BindableCore.luau"}}')}}]);